settings.customCss:
.mfp-easter-werkhaus{--mf-surface:#f4f1e8;--mf-ink:#1c1b16;--mf-muted:#5f5a4c;--mf-line:#b8b09c;--mf-control:#fdfcf7;--mf-action:#c22f1e;--mf-action-ink:#ffffff;--mf-focus:#1f4fa3;--mf-error:#8f1d1d;--mf-accent:#e9b32a;--mf-art:#efe7d3;box-sizing:border-box;display:grid;grid-template-columns:minmax(0,0.75fr) minmax(0,1.6fr);gap:0;padding:0;width:100%;max-width:940px;margin:0 auto;border:2px solid var(--mf-ink);border-radius:0;background:var(--mf-surface);box-shadow:12px 12px 0 var(--mf-accent);color:var(--mf-ink);font-family:"Helvetica Neue",Helvetica,Arial,system-ui,sans-serif;font-size:16px;line-height:1.5;letter-spacing:0}
.mfp-easter-werkhaus *{box-sizing:border-box;min-width:0}
.mfp-easter-werkhaus .form-art{margin:0;position:relative;overflow:hidden;background:var(--mf-art);border-right:2px solid var(--mf-ink)}
.mfp-easter-werkhaus .form-art img{position:absolute;inset:0;display:block;width:100%;height:100%;object-fit:cover;object-position:38% center}
.mfp-easter-werkhaus .form-content{padding:30px 32px 28px}
.mfp-easter-werkhaus .form-kicker{display:flex;align-items:center;gap:9px;margin:0 0 12px;color:var(--mf-action);font-size:12px;font-weight:700;letter-spacing:0.18em;text-transform:uppercase}
.mfp-easter-werkhaus .kicker-mark{display:inline-block;width:12px;height:12px;background:var(--mf-action)}
.mfp-easter-werkhaus h2{margin:0 0 8px;font-family:inherit;font-size:34px;font-weight:700;line-height:1.08;letter-spacing:-0.01em;overflow-wrap:anywhere}
.mfp-easter-werkhaus .form-heading p:last-child{margin:0;color:var(--mf-muted);font-size:14px}
.mfp-easter-werkhaus .form-fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px 22px;margin-top:26px;padding-top:24px;border-top:3px solid var(--mf-ink)}
.mfp-easter-werkhaus .field-wide{grid-column:1 / -1}
.mfp-easter-werkhaus .field-group{overflow-wrap:anywhere}
.mfp-easter-werkhaus .q-no{display:block;margin-bottom:8px;color:var(--mf-action);font-size:12px;font-weight:700;letter-spacing:0.1em}
.mfp-easter-werkhaus .field-slot label{display:block;margin-bottom:8px;font-size:11px;font-weight:700;letter-spacing:0.12em;text-transform:uppercase;color:var(--mf-ink)}
.mfp-easter-werkhaus .field-slot small{display:block;margin-top:7px;font-size:12px;color:var(--mf-muted)}
.mfp-easter-werkhaus .field-slot input{display:block;width:100%;min-height:46px;padding:10px 12px;border:1.5px solid var(--mf-ink);border-radius:0;background:var(--mf-control);color:var(--mf-ink);font:inherit;font-size:16px}
.mfp-easter-werkhaus .field-slot input:focus-visible{outline:3px solid var(--mf-focus);outline-offset:2px}
.mfp-easter-werkhaus .field-slot input::placeholder{color:var(--mf-muted);opacity:1}
.mfp-easter-werkhaus .field-slot select{display:block;width:100%;min-height:46px;padding:10px 12px;border:1.5px solid var(--mf-ink);border-radius:0;background:var(--mf-control);color:var(--mf-ink);font:inherit;font-size:16px}
.mfp-easter-werkhaus .field-slot select:focus-visible{outline:3px solid var(--mf-focus);outline-offset:2px}
.mfp-easter-werkhaus .field-slot textarea{display:block;width:100%;min-height:82px;padding:10px 12px;border:1.5px solid var(--mf-ink);border-radius:0;background:var(--mf-control);color:var(--mf-ink);font:inherit;font-size:16px;resize:vertical}
.mfp-easter-werkhaus .field-slot textarea:focus-visible{outline:3px solid var(--mf-focus);outline-offset:2px}
.mfp-easter-werkhaus .field-slot textarea::placeholder{color:var(--mf-muted);opacity:1}
.mfp-easter-werkhaus .form-actions{margin-top:26px}
.mfp-easter-werkhaus .form-actions button{display:flex;align-items:center;justify-content:space-between;gap:12px;width:100%;min-height:52px;padding:12px 18px;border:2px solid var(--mf-ink);border-radius:0;background:var(--mf-action);color:var(--mf-action-ink);font:inherit;font-size:13px;font-weight:700;letter-spacing:0.14em;text-transform:uppercase;cursor:pointer}
.mfp-easter-werkhaus .form-actions button .btn-mark{font-size:18px;letter-spacing:0}
.mfp-easter-werkhaus .form-actions button:hover{filter:brightness(0.92)}
.mfp-easter-werkhaus .form-actions button:focus-visible{outline:3px solid var(--mf-focus);outline-offset:3px}
.mfp-easter-werkhaus .form-actions button:disabled{opacity:.65;cursor:wait}
.mfp-easter-werkhaus .form-footer{margin-top:16px;padding-top:12px;border-top:1px solid var(--mf-line);color:var(--mf-muted);font-size:12px}
.mfp-easter-werkhaus .field-slot [aria-invalid="true"]{border-color:var(--mf-error)}
.mfp-easter-werkhaus .field-slot [role="alert"]{color:var(--mf-error);font-size:12px;margin:6px 0 0}
.mfp-easter-werkhaus [role="status"]{color:var(--mf-ink);overflow-wrap:anywhere}
@media(max-width:680px){.mfp-easter-werkhaus{grid-template-columns:1fr;box-shadow:8px 8px 0 var(--mf-accent)}.mfp-easter-werkhaus .form-art{height:160px;border-right:0;border-bottom:2px solid var(--mf-ink)}.mfp-easter-werkhaus .form-art img{object-position:center 55%}.mfp-easter-werkhaus .form-content{padding:22px 20px 24px}.mfp-easter-werkhaus h2{font-size:28px}.mfp-easter-werkhaus .form-fields{grid-template-columns:1fr;margin-top:22px;padding-top:20px;gap:18px}}
